        IF recipe[tmp_index].recipeID = recipeIn.recipeID AND recipeIn.recipeID <> 0 THEN
            tmp_found := TRUE;
            EXIT;
        END_IF
    END_FOR

    IF tmp_found THEN
        recipeQueryResult := recipe[tmp_index];
    ELSE
        error := TRUE;
        status := 16#8001;
    END_IF
END_IF

// Add Operation
IF addRecipe THEN
    tmp_found := FALSE;
    tmp_hasEmpty := FALSE;
    tmp_emptySlot := 0;

    // Check if recipe ID already exists
    FOR tmp_index := 1 TO 10 DO
        IF recipe[tmp_index].recipeID = recipeIn.recipeID THEN
            tmp_found := TRUE;
            EXIT;
        END_IF
        IF recipe[tmp_index].recipeID = 0 AND NOT tmp_hasEmpty THEN
            tmp_hasEmpty := TRUE;
            tmp_emptySlot := tmp_index;
        END_IF
    END_FOR

    IF tmp_found THEN
        error := TRUE;
        status := 16#8002;
    ELSIF NOT tmp_hasEmpty THEN
        error := TRUE;
        status := 16#8003;
    ELSE
        recipe[tmp_emptySlot] := recipeIn;
        recipeAdded := TRUE;
    END_IF
END_IF

// Delete Operation
IF deleteRecipe THEN
    tmp_found := FALSE;
    tmp_index := 1;

    FOR tmp_index := 1 TO 10 DO
        IF recipe[tmp_index].recipeID = recipeIn.recipeID THEN
            tmp_found := TRUE;
            EXIT;
        END_IF
    END_FOR

    IF tmp_found THEN
        recipe[tmp_index].recipeID := 0;
        recipeDeleted := TRUE;
    ELSE
        error := TRUE;
        status := 16#8004;
    END_IF
END_IF

// Modify Operation
IF modifyRecipe THEN
    tmp_found := FALSE;
    tmp_index := 1;

    FOR tmp_index := 1 TO 10 DO
        IF recipe[tmp_index].recipeID = recipeIn.recipeID THEN
            tmp_found := TRUE;
            EXIT;
        END_IF
    END_FOR

    IF tmp_found THEN
        recipe[tmp_index] := recipeIn;
        recipeModified := TRUE;
    ELSE
        error := TRUE;
        status := 16#8005;
    END_IF
END_IF
